34	};
35	
36	#define NO_EVENT                    0
37	#define EVT_BUTTON_SINGLE_CLICK     0x01
38	#define EVT_BUTTON_DOUBLE_CLICK     0x02
39	#define EVT_BUTTON_DOWN_LONG        0x04
40	#define EVT_UP                  0x10
41	#define EVT_DOWN                0x20
42	#define EVT_REPEAT              0x40
43	
44	#define BUTTON_DOWN_LONG_TICKS      5000   /* 1sec */
45	#define BUTTON_DOUBLE_TICKS         2500   /* 500ms */
46	#define BUTTON_REPEAT_TICKS         625    /* 125ms */
47	#define BUTTON_DEBOUNCE_TICKS       200
48	
49	/* lever switch assignment */
50	#define BIT_UP1     3
51	#define BIT_PUSH    2
52	#define BIT_DOWN1   1
53	
54	#define READ_PORT() palReadPort(GPIOA)
55	#define BUTTON_MASK 0b1111
56	
57	static uint16_t last_button = 0b0000;
58	static uint32_t last_button_down_ticks;
59	static uint32_t last_button_repeat_ticks;
60	static int8_t inhibit_until_release = FALSE;
61	
62	volatile uint8_t operation_requested = OP_NONE;
63	
64	int8_t previous_marker = -1;
65	
66	enum {
67	  UI_NORMAL, UI_MENU, UI_NUMERIC, UI_KEYPAD
68	};
69	
70	enum {
71	  KM_START, KM_STOP, KM_CENTER, KM_SPAN, KM_CW, KM_SCALE, KM_REFPOS, KM_EDELAY, KM_VELOCITY_FACTOR, KM_SCALEDELAY
72	};
