74	#define NUMINPUT_LEN 10
75	
76	static uint8_t ui_mode = UI_NORMAL;
77	static uint8_t keypad_mode;
78	static uint8_t keypads_last_index;
79	static char    kp_buf[NUMINPUT_LEN+1];
80	static int8_t  kp_index = 0;
81	static uint8_t menu_current_level = 0;
82	static int8_t  selection = 0;
83	
84	// Set structure align as WORD (save flash memory)
85	#pragma pack(push, 2)
