94	// Touch screen
95	#define EVT_TOUCH_NONE     0
96	#define EVT_TOUCH_DOWN     1
97	#define EVT_TOUCH_PRESSED  2
98	#define EVT_TOUCH_RELEASED 3
99	
100	static int8_t last_touch_status = EVT_TOUCH_NONE;
101	static int16_t last_touch_x;
102	static int16_t last_touch_y;
103	
104	//int16_t touch_cal[4] = { 1000, 1000, 10*16, 12*16 };
105	//int16_t touch_cal[4] = { 620, 600, 130, 180 };
106	
107	//int awd_count;
108	//int touch_x, touch_y;
109	
110	#define KP_CONTINUE 0
111	#define KP_DONE 1
112	#define KP_CANCEL 2
113	
114	static void ui_mode_normal(void);
115	static void ui_mode_menu(void);
116	static void ui_mode_numeric(int _keypad_mode);
117	static void ui_mode_keypad(int _keypad_mode);
118	static void draw_menu(void);
