126	
127	static int btn_check(void)
128	{
129	    int cur_button = READ_PORT() & BUTTON_MASK;
130	    int changed = last_button ^ cur_button;
131	    int status = 0;
132	    uint32_t ticks = chVTGetSystemTime();
133	    if (changed & (1<<BIT_PUSH)) {
134	      if ((cur_button & (1<<BIT_PUSH))
135	          && ticks >= last_button_down_ticks + BUTTON_DEBOUNCE_TICKS) {
136	        // button released
137	        status |= EVT_BUTTON_SINGLE_CLICK;
138	        if (inhibit_until_release) {
139	          status = 0;
140	          inhibit_until_release = FALSE;
141	        }
142	      }
143	    }
144	    if (changed & (1<<BIT_UP1)) {
145	      if ((cur_button & (1<<BIT_UP1))
146	          && (ticks >= last_button_down_ticks + BUTTON_DEBOUNCE_TICKS)) {
147	        status |= EVT_UP;
148	      }
149	    }
150	    if (changed & (1<<BIT_DOWN1)) {
151	      if ((cur_button & (1<<BIT_DOWN1))
152	          && (ticks >= last_button_down_ticks + BUTTON_DEBOUNCE_TICKS)) {
153	        status |= EVT_DOWN;
154	      }
155	    }
156	    last_button_down_ticks = ticks;
157	    last_button = cur_button;
158	
159	    return status;
160	}
161	
162	static int btn_wait_release(void)
163	{
164	  while (TRUE) {
165	    int cur_button = READ_PORT() & BUTTON_MASK;
166	    int changed = last_button ^ cur_button;
167	    uint32_t ticks = chVTGetSystemTime();
168	    int status = 0;
169	    if (!inhibit_until_release) {
170	      if ((cur_button & (1<<BIT_PUSH))
171	          && ticks >= last_button_down_ticks + BUTTON_DOWN_LONG_TICKS) {
172	        inhibit_until_release = TRUE;
173	        return EVT_BUTTON_DOWN_LONG;
174	      }
175	      if ((changed & (1<<BIT_PUSH))
176	          && ticks < last_button_down_ticks + BUTTON_DOWN_LONG_TICKS) {
177	        return EVT_BUTTON_SINGLE_CLICK;
178	      }
179	    }
180	
181	    if (changed) {
182	      // finished
183	      last_button = cur_button;
184	      last_button_down_ticks = ticks;
185	      inhibit_until_release = FALSE;
186	      return 0;
187	    }
188	
189	    if (ticks >= last_button_down_ticks + BUTTON_DOWN_LONG_TICKS
190	        && ticks >=  last_button_repeat_ticks + BUTTON_REPEAT_TICKS) {
191	      if (cur_button & (1<<BIT_DOWN1))
192	        status |= EVT_DOWN | EVT_REPEAT;
193	      if (cur_button & (1<<BIT_UP1))
194	        status |= EVT_UP | EVT_REPEAT;
195	      last_button_repeat_ticks = ticks;
196	      return status;
197	    }
198	  }
199	}
200	
201	static int
202	touch_measure_y(void)
203	{
204	  int v;
205	  // open Y line
206	  palSetPadMode(GPIOB, 1, PAL_MODE_INPUT_PULLDOWN );
207	  palSetPadMode(GPIOA, 7, PAL_MODE_INPUT_PULLDOWN );
208	  // drive low to high on X line
209	  palSetPadMode(GPIOB, 0, PAL_MODE_OUTPUT_PUSHPULL );
210	  palClearPad(GPIOB, 0);
211	  palSetPadMode(GPIOA, 6, PAL_MODE_OUTPUT_PUSHPULL );
212	  palSetPad(GPIOA, 6);
213	
214	  chThdSleepMilliseconds(2);
215	  v = adc_single_read(ADC_CHSELR_CHSEL7);
216	  //chThdSleepMilliseconds(2);
217	  //v += adc_single_read(ADC1, ADC_CHSELR_CHSEL7);
218	  return v;
219	}
220	
221	static int
222	touch_measure_x(void)
223	{
224	  int v;
225	  // open X line
226	  palSetPadMode(GPIOB, 0, PAL_MODE_INPUT_PULLDOWN );
227	  palSetPadMode(GPIOA, 6, PAL_MODE_INPUT_PULLDOWN );
228	  // drive low to high on Y line
229	  palSetPadMode(GPIOB, 1, PAL_MODE_OUTPUT_PUSHPULL );
230	  palSetPad(GPIOB, 1);
231	  palSetPadMode(GPIOA, 7, PAL_MODE_OUTPUT_PUSHPULL );
232	  palClearPad(GPIOA, 7);
233	
234	  chThdSleepMilliseconds(2);
235	  v = adc_single_read(ADC_CHSELR_CHSEL6);
236	  //chThdSleepMilliseconds(2);
237	  //v += adc_single_read(ADC1, ADC_CHSELR_CHSEL6);
238	  return v;
239	}
240	
241	void
242	touch_prepare_sense(void)
243	{
244	  // open Y line
245	  palSetPadMode(GPIOB, 1, PAL_MODE_INPUT_PULLDOWN );
246	  palSetPadMode(GPIOA, 7, PAL_MODE_INPUT_PULLDOWN );
247	  // force high X line
248	  palSetPadMode(GPIOB, 0, PAL_MODE_OUTPUT_PUSHPULL );
249	  palSetPad(GPIOB, 0);
250	  palSetPadMode(GPIOA, 6, PAL_MODE_OUTPUT_PUSHPULL );
251	  palSetPad(GPIOA, 6);
252	}
253	
254	void
255	touch_start_watchdog(void)
256	{
257	  touch_prepare_sense();
258	  adc_start_analog_watchdogd(ADC_CHSELR_CHSEL7);
259	}
260	
261	static int
262	touch_status(void)
263	{
264	  touch_prepare_sense();
265	  return adc_single_read(ADC_CHSELR_CHSEL7) > TOUCH_THRESHOLD;
266	}
267	
268	static int
269	touch_check(void)
270	{
271	  int stat = touch_status();
272	  if (stat) {
273	    chThdSleepMilliseconds(10);
274	    int x = touch_measure_x();
275	    int y = touch_measure_y();
276	    if (touch_status()) {
277	      last_touch_x = x;
278	      last_touch_y = y;
279	    }
280	    touch_prepare_sense();
281	  }
282	
283	  if (stat != last_touch_status) {
284	    last_touch_status = stat;
285	    return stat ? EVT_TOUCH_PRESSED : EVT_TOUCH_RELEASED;
286	  }
287	  return stat ? EVT_TOUCH_DOWN : EVT_TOUCH_NONE;
288	}
