304	void
305	touch_cal_exec(void)
306	{
307	  int x1, x2, y1, y2;
308	
309	  adc_stop();
310	  ili9341_set_foreground(DEFAULT_FG_COLOR);
311	  ili9341_set_background(DEFAULT_BG_COLOR);
312	  ili9341_clear_screen();
313	  ili9341_line(0, 0, 0, 32);
314	  ili9341_line(0, 0, 32, 0);
315	  ili9341_drawstring("TOUCH UPPER LEFT", 10, 10);
316	
317	  touch_wait_release();
318	  x1 = last_touch_x;
319	  y1 = last_touch_y;
320	
321	  ili9341_clear_screen();
322	  ili9341_line(320-1, 240-1, 320-1, 240-32);
323	  ili9341_line(320-1, 240-1, 320-32, 240-1);
324	  ili9341_drawstring("TOUCH LOWER RIGHT", 230, 220);
325	
326	  touch_wait_release();
327	  x2 = last_touch_x;
328	  y2 = last_touch_y;
329	
330	  config.touch_cal[0] = x1;
331	  config.touch_cal[1] = y1;
332	  config.touch_cal[2] = (x2 - x1) * 16 / 320;
333	  config.touch_cal[3] = (y2 - y1) * 16 / 240;
334	
335	  //redraw_all();
336	  touch_start_watchdog();
337	}
