696	static uint32_t
697	get_marker_frequency(int marker)
698	{
699	  if (marker < 0 || marker >= MARKERS_MAX)
700	    return 0;
701	  if (!markers[marker].enabled)
702	    return 0;
703	  return frequencies[markers[marker].index];
704	}
705	
706	static void
707	menu_marker_op_cb(int item, uint8_t data)
708	{
709	  uint32_t freq = get_marker_frequency(active_marker);
710	  if (freq == 0)
711	    return; // no active marker
712	
713	  switch (item) {
714	  case 0: /* MARKER->START */
715	  case 1: /* MARKER->STOP */
716	  case 2: /* MARKER->CENTER */
717	    set_sweep_frequency(data, freq);
718	    break;
719	  case 3: /* MARKERS->SPAN */
720	    {
721	      if (previous_marker == -1 || active_marker == previous_marker) {
722	        // if only 1 marker is active, keep center freq and make span the marker comes to the edge
723	        uint32_t center = get_sweep_frequency(ST_CENTER);
724	        uint32_t span = center > freq ? center - freq : freq - center;
725	        set_sweep_frequency(ST_SPAN, span * 2);
726	      } else {
727	        // if 2 or more marker active, set start and stop freq to each marker
728	        uint32_t freq2 = get_marker_frequency(previous_marker);
729	        if (freq2 == 0)
730	          return;
731	        if (freq > freq2) {
732	          freq2 = freq;
733	          freq = get_marker_frequency(previous_marker);
734	        }
735	        set_sweep_frequency(ST_START, freq);
736	        set_sweep_frequency(ST_STOP, freq2);
737	      }
738	    }
739	    break;
740	  case 4: /* MARKERS->EDELAY */
741	    { 
742	      if (uistat.current_trace == -1)
743	        break;
744	      float (*array)[2] = measured[trace[uistat.current_trace].channel];
745	      float v = groupdelay_from_array(markers[active_marker].index, array);
746	      set_electrical_delay(electrical_delay + (v / 1e-12));
747	    }
748	    break;
749	  }
750	  ui_mode_normal();
751	  draw_cal_status();
752	  //redraw_all();
753	}
