797	static void
798	active_marker_select(int item)
799	{
800	  if (item == -1) {
801	    active_marker = previous_marker;
802	    previous_marker = -1;
803	    if (active_marker == -1) {
804	      choose_active_marker();
805	    }
806	  } else {
807	    if (previous_marker != active_marker)
808	      previous_marker = active_marker;
809	    active_marker = item;
810	  }
811	}
