814	menu_marker_sel_cb(int item, uint8_t data)
815	{
816	  (void)data;
817	  int t;
818	  if (item >= 0 && item < MARKERS_MAX) {
819	    if (markers[item].enabled) {
820	      if (item == active_marker) {
821	        // disable if active trace is selected
822	        markers[item].enabled = FALSE;
823	        active_marker_select(-1);
824	      } else {
825	        active_marker_select(item);
826	      }
827	    } else {
828	      markers[item].enabled = TRUE;
829	      active_marker_select(item);
830	    }
831	  } else if (item == 4) { /* all off */
832	      for (t = 0; t < MARKERS_MAX; t++)
833	        markers[t].enabled = FALSE;
834	      previous_marker = -1;
835	      active_marker = -1;      
836	  } else if (item == 5) { /* marker delta */
837	    uistat.marker_delta = !uistat.marker_delta;
838	  }
839	  redraw_marker(active_marker);
840	  draw_menu();
841	}
