1112	menu_invoke(int item)
1113	{
1114	  const menuitem_t *menu = menu_stack[menu_current_level];
1115	  menu = &menu[item];
1116	
1117	  switch (menu->type) {
1118	  case MT_NONE:
1119	  case MT_BLANK:
1120	  case MT_CLOSE:
1121	    ui_mode_normal();
1122	    break;
1123	
1124	  case MT_CANCEL:
1125	    menu_move_back();
1126	    break;
1127	
1128	  case MT_CALLBACK: {
1129	    menuaction_cb_t cb = (menuaction_cb_t)menu->reference;
1130	    if (cb == NULL)
1131	      return;
1132	    (*cb)(item, menu->data);
1133	    break;
1134	  }
1135	
1136	  case MT_SUBMENU:
1137	    menu_push_submenu((const menuitem_t*)menu->reference);
1138	    break;
1139	  }
1140	}
