1289	static void
1290	draw_numeric_input(const char *buf)
1291	{
1292	  int i;
1293	  int x;
1294	  int focused = FALSE;
1295	  uint16_t xsim = 0b0010010000000000;
1296	
1297	  for (i = 0, x = 64; i < 10 && buf[i]; i++, xsim<<=1) {
1298	    uint16_t fg = DEFAULT_MENU_TEXT_COLOR;
1299	    uint16_t bg = config.menu_normal_color;
1300	    int c = buf[i];
1301	    if (c == '.')
1302	      c = KP_PERIOD;
1303	    else if (c == '-')
1304	      c = KP_MINUS;
1305	    else// if (c >= '0' && c <= '9')
1306	      c = c - '0';
1307	
1308	    if (ui_mode == UI_NUMERIC && uistat.digit == 8-i) {
1309	      fg = DEFAULT_SPEC_INPUT_COLOR;
1310	      focused = TRUE;
1311	//      if (uistat.digit_mode)
1312	//        bg = DEFAULT_MENU_COLOR;
1313	    }
1314	    ili9341_set_foreground(fg);
1315	    ili9341_set_background(bg);
1316	    if (c >= 0) // c is number
1317	      ili9341_drawfont(c, x, 240-NUM_INPUT_HEIGHT+4);
1318	    else if (focused) // c not number, but focused
1319	      ili9341_drawfont(0, x, 240-NUM_INPUT_HEIGHT+4);
1320	    else // erase
1321	      ili9341_fill(x, 240-NUM_INPUT_HEIGHT+4, NUM_FONT_GET_HEIGHT, NUM_FONT_GET_WIDTH+2+8, bg);
1322	
1323	    x += xsim&0x8000 ? NUM_FONT_GET_WIDTH+2+8 : NUM_FONT_GET_WIDTH+2;
1324	  }
1325	  // erase last
1326	  ili9341_fill(x, 240-NUM_INPUT_HEIGHT+4, NUM_FONT_GET_WIDTH+2+8, NUM_FONT_GET_WIDTH+2+8, config.menu_normal_color);
1327	}
