1340	static void
1341	menu_item_modify_attribute(const menuitem_t *menu, int item,
1342	                           uint16_t *fg, uint16_t *bg)
1343	{
1344	  if (menu == menu_trace && item < TRACES_MAX) {
1345	    if (trace[item].enabled)
1346	      *bg = config.trace_color[item];
1347	  } else if (menu == menu_marker_sel) {
1348	    if (item < 4) {
1349	      if (markers[item].enabled) {
1350	        *bg = DEFAULT_MENU_TEXT_COLOR;
1351	        *fg = config.menu_normal_color;
1352	      }
1353	    } else if (item == 5) {
1354	      if (uistat.marker_delta) {
1355	        *bg = DEFAULT_MENU_TEXT_COLOR;
1356	        *fg = config.menu_normal_color;
1357	      }
1358	    }
1359	  } else if (menu == menu_marker_search) {
1360	    if (item == 4 && uistat.marker_tracking) {
1361	      *bg = DEFAULT_MENU_TEXT_COLOR;
1362	      *fg = config.menu_normal_color;
1363	    }
1364	  } else if (menu == menu_marker_smith) {
1365	
1366	    if (marker_smith_format == item) {
1367	      *bg = DEFAULT_MENU_TEXT_COLOR;
1368	      *fg = config.menu_normal_color;
1369	    }
1370	  } else if (menu == menu_calop) {
1371	    if ((item == 0 && (cal_status & CALSTAT_OPEN))
1372	        || (item == 1 && (cal_status & CALSTAT_SHORT))
1373	        || (item == 2 && (cal_status & CALSTAT_LOAD))
1374	        || (item == 3 && (cal_status & CALSTAT_ISOLN))
1375	        || (item == 4 && (cal_status & CALSTAT_THRU))) {
1376	      domain_mode = (domain_mode & ~DOMAIN_MODE) | DOMAIN_FREQ;
1377	      *bg = DEFAULT_MENU_TEXT_COLOR;
1378	      *fg = config.menu_normal_color;
1379	    }
1380	  } else if (menu == menu_stimulus) {
1381	    if (item == 5 /* PAUSE */ && !(sweep_mode&SWEEP_ENABLE)) {
1382	      *bg = DEFAULT_MENU_TEXT_COLOR;
1383	      *fg = config.menu_normal_color;
1384	    }
1385	  } else if (menu == menu_cal) {
1386	    if (item == 3 /* CORRECTION */ && (cal_status & CALSTAT_APPLY)) {
1387	      *bg = DEFAULT_MENU_TEXT_COLOR;
1388	      *fg = config.menu_normal_color;
1389	    }
1390	  } else if (menu == menu_bandwidth) {
1391	      if (item == bandwidth) {
1392	        *bg = 0x0000;
1393	        *fg = 0xffff;
1394	      }
1395	  } else if (menu == menu_transform) {
1396	      if ((item == 0 && (domain_mode & DOMAIN_MODE) == DOMAIN_TIME)
1397	       || (item == 1 && (domain_mode & TD_FUNC) == TD_FUNC_LOWPASS_IMPULSE)
1398	       || (item == 2 && (domain_mode & TD_FUNC) == TD_FUNC_LOWPASS_STEP)
1399	       || (item == 3 && (domain_mode & TD_FUNC) == TD_FUNC_BANDPASS)
1400	       ) {
1401	        *bg = DEFAULT_MENU_TEXT_COLOR;
1402	        *fg = config.menu_normal_color;
1403	      }
1404	  } else if (menu == menu_transform_window) {
1405	      if ((item == 0 && (domain_mode & TD_WINDOW) == TD_WINDOW_MINIMUM)
1406	       || (item == 1 && (domain_mode & TD_WINDOW) == TD_WINDOW_NORMAL)
1407	       || (item == 2 && (domain_mode & TD_WINDOW) == TD_WINDOW_MAXIMUM)
1408	       ) {
1409	        *bg = DEFAULT_MENU_TEXT_COLOR;
1410	        *fg = config.menu_normal_color;
1411	      }
1412	  }
1413	}
