1415	static void
1416	draw_menu_buttons(const menuitem_t *menu)
1417	{
1418	  int i = 0;
1419	  for (i = 0; i < MENU_BUTTON_MAX; i++) {
1420	    const char *l1, *l2;
1421	    if (menu[i].type == MT_NONE)
1422	      break;
1423	    if (menu[i].type == MT_BLANK)
1424	      continue;
1425	    int y = MENU_BUTTON_HEIGHT*i;
1426	    uint16_t bg = config.menu_normal_color;
1427	    uint16_t fg = DEFAULT_MENU_TEXT_COLOR;
1428	    // focus only in MENU mode but not in KEYPAD mode
1429	    if (ui_mode == UI_MENU && i == selection)
1430	      bg = config.menu_active_color;
1431	    ili9341_fill(320-MENU_BUTTON_WIDTH, y, MENU_BUTTON_WIDTH, MENU_BUTTON_HEIGHT-2, bg);
1432	    
1433	    menu_item_modify_attribute(menu, i, &fg, &bg);
1434	    ili9341_set_foreground(fg);
1435	    ili9341_set_background(bg);
1436	    if (menu_is_multiline(menu[i].label, &l1, &l2)) {
