1705	// ex. 10942 -> 10000
1706	//      6791 ->  5000
1707	//       341 ->   200
1708	static uint32_t
1709	step_round(uint32_t v)
1710	{
1711	  // decade step
1712	  uint32_t x = 1;
1713	  for (x = 1; x*10 < v; x*= 10)
1714	    ;
1715	
1716	  // 1-2-5 step
1717	  if (x * 2 > v)
1718	    return x;
1719	  else if (x * 5 > v)
1720	    return x * 2;
1721	  else
1722	    return x * 5;
1723	}
