1725	static void
1726	lever_zoom_span(int status)
1727	{
1728	  uint32_t span = get_sweep_frequency(ST_SPAN);
1729	  if (status & EVT_UP) {
1730	    span = step_round(span - 1);
1731	  } else if (status & EVT_DOWN) {
1732	    span = step_round(span + 1);
1733	    span = step_round(span * 3);
1734	  }
1735	  set_sweep_frequency(ST_SPAN, span);
1736	}
