1738	static void
1739	lever_move(int status, int mode)
1740	{
1741	  uint32_t center = get_sweep_frequency(mode);
1742	  uint32_t span = get_sweep_frequency(ST_SPAN);
1743	  span = step_round(span / 3);
1744	  if (status & EVT_UP) {
1745	    set_sweep_frequency(mode, center + span);
1746	  } else if (status & EVT_DOWN) {
1747	    set_sweep_frequency(mode, center - span);
1748	  }
1749	}
