1751	#define STEPRATIO 0.2
1752	
1753	static void
1754	lever_edelay(int status)
1755	{
1756	  float value = get_electrical_delay();
1757	  float ratio = STEPRATIO;
1758	  if (value < 0)
1759	    ratio = -ratio;
1760	  if (status & EVT_UP) {
1761	    value = (1 - ratio) * value;
1762	  } else if (status & EVT_DOWN) {
1763	    value = (1 + ratio) * value;
1764	  }
1765	  set_electrical_delay(value);
1766	}
