1827	static int
1828	keypad_click(int key)
1829	{
1830	  int c = keypads[key].c;
1831	  if ((c >= KP_X1 && c <= KP_G) || c == KP_N || c == KP_P) {
1832	    int32_t scale = 1;
1833	    if (c >= KP_X1 && c <= KP_G) {
1834	      int n = c - KP_X1;
1835	      while (n-- > 0)
1836	        scale *= 1000;
1837	    } else if (c == KP_N) {
1838	      scale *= 1000;
1839	    }
1840	    /* numeric input done */
1841	    double value = my_atof(kp_buf) * scale;
1842	    switch (keypad_mode) {
1843	    case KM_START:
1844	      set_sweep_frequency(ST_START, value);
1845	      break;
1846	    case KM_STOP:
1847	      set_sweep_frequency(ST_STOP, value);
1848	      break;
1849	    case KM_CENTER:
1850	      set_sweep_frequency(ST_CENTER, value);
1851	      break;
1852	    case KM_SPAN:
1853	      set_sweep_frequency(ST_SPAN, value);
1854	      break;
1855	    case KM_CW:
1856	      set_sweep_frequency(ST_CW, value);
1857	      break;
1858	    case KM_SCALE:
1859	      set_trace_scale(uistat.current_trace, value);
1860	      break;
1861	    case KM_REFPOS:
1862	      set_trace_refpos(uistat.current_trace, value);
1863	      break;
1864	    case KM_EDELAY:
1865	      set_electrical_delay(value); // pico seconds
1866	      break;
1867	    case KM_VELOCITY_FACTOR:
1868	      velocity_factor = value / 100.0;
1869	      break;
1870	    case KM_SCALEDELAY:
1871	      set_trace_scale(uistat.current_trace, value * 1e-12); // pico second
1872	      break;
1873	    }
1874	
1875	    return KP_DONE;
1876	  } else if (c <= 9 && kp_index < NUMINPUT_LEN) {
1877	    kp_buf[kp_index++] = '0' + c;
1878	  } else if (c == KP_PERIOD && kp_index < NUMINPUT_LEN) {
1879	    // check period in former input
1880	    int j;
1881	    for (j = 0; j < kp_index && kp_buf[j] != '.'; j++)
1882	      ;
1883	    // append period if there are no period
1884	    if (kp_index == j)
1885	      kp_buf[kp_index++] = '.';
1886	  } else if (c == KP_MINUS) {
1887	    if (kp_index == 0)
1888	      kp_buf[kp_index++] = '-';
1889	  } else if (c == KP_BS) {
1890	    if (kp_index == 0) {
1891	      return KP_CANCEL;
1892	    }
1893	    --kp_index;
1894	  }
1895	  kp_buf[kp_index] = '\0';
1896	  draw_numeric_input(kp_buf);
1897	  return KP_CONTINUE;
1898	}
