1926	static void
1927	numeric_apply_touch(void)
1928	{
1929	  int touch_x, touch_y;
1930	  touch_position(&touch_x, &touch_y);
1931	
1932	  if (touch_x < 64) {
1933	    ui_mode_normal();
1934	    return;
1935	  }
1936	  if (touch_x > 64+9*20+8+8) {
1937	    ui_mode_keypad(keypad_mode);
1938	    ui_process_keypad();
1939	    return;
1940	  }
1941	
1942	  if (touch_y > 240-40) {
1943	    int n = 9 - (touch_x - 64) / 20;
1944	    uistat.digit = n;
1945	    uistat.digit_mode = TRUE;
1946	  } else {
1947	    int step, n;
1948	    if (touch_y < 100) {
1949	      step = 1;
1950	    } else {
1951	      step = -1;
1952	    }
1953	
1954	    for (n = uistat.digit; n > 0; n--)
1955	      step *= 10;
1956	    uistat.value += step;
1957	  }
1958	  draw_numeric_area();
1959	
1960	  touch_wait_release();
1961	  uistat.digit_mode = FALSE;
1962	  draw_numeric_area();
1963	
1964	  return;
1965	}
