1967	static void
1968	ui_process_numeric(void)
1969	{
1970	  int status = btn_check();
1971	
1972	  if (status != 0) {
1973	    if (status == EVT_BUTTON_SINGLE_CLICK) {
1974	      status = btn_wait_release();
1975	      if (uistat.digit_mode) {
1976	        if (status & (EVT_BUTTON_SINGLE_CLICK | EVT_BUTTON_DOWN_LONG)) {
1977	          uistat.digit_mode = FALSE;
1978	          draw_numeric_area();
1979	        }
1980	      } else {
1981	        if (status & EVT_BUTTON_DOWN_LONG) {
1982	          uistat.digit_mode = TRUE;
1983	          draw_numeric_area();
1984	        } else if (status & EVT_BUTTON_SINGLE_CLICK) {
1985	          set_numeric_value();
1986	          ui_mode_normal();
1987	        }
1988	      }
1989	    } else {
1990	      do {
1991	        if (uistat.digit_mode) {
1992	          if (status & EVT_DOWN) {
1993	            if (uistat.digit < 8)
1994	              uistat.digit++;
1995	            else
1996	              goto exit;
1997	          }
1998	          if (status & EVT_UP) {
1999	            if (uistat.digit > 0)
2000	              uistat.digit--;
2001	            else
2002	              goto exit;
2003	          }
2004	        } else {
2005	          int32_t step = 1;
2006	          int n;
2007	          for (n = uistat.digit; n > 0; n--)
2008	            step *= 10;
2009	          if (status & EVT_DOWN)
2010	            uistat.value += step;
2011	          if (status & EVT_UP)
2012	            uistat.value -= step;
2013	        }
2014	        draw_numeric_area();
2015	        status = btn_wait_release();
2016	      } while (status != 0);
2017	    }
2018	  }
2019	
2020	  return;
2021	
2022	 exit:
2023	  // cancel operation
2024	  ui_mode_normal();
2025	}
