2027	static void
2028	ui_process_keypad(void)
2029	{
2030	  int status;
2031	  adc_stop();
2032	
2033	  kp_index = 0;
2034	  while (TRUE) {
2035	    status = btn_check();
2036	    if (status & (EVT_UP|EVT_DOWN)) {
2037	      int s = status;
2038	      do {
2039	        if (s & EVT_UP)
2040	          if (--selection < 0)
2041	            selection = keypads_last_index;
2042	        if (s & EVT_DOWN)
2043	          if (++selection > keypads_last_index)
2044	            selection = 0;
2045	        draw_keypad();
2046	        s = btn_wait_release();
2047	      } while (s != 0);
2048	    }
2049	
2050	    if (status == EVT_BUTTON_SINGLE_CLICK) {
2051	      if (keypad_click(selection))
2052	        /* exit loop on done or cancel */
2053	        break;
2054	    }
2055	
2056	    if (touch_check() == EVT_TOUCH_PRESSED) {
2057	      int key = keypad_apply_touch();
2058	      if (key >= 0 && keypad_click(key))
2059	        /* exit loop on done or cancel */
2060	        break;
2061	    }
2062	  }
2063	
2064	  redraw_frame();
2065	  request_to_redraw_grid();
2066	  ui_mode_normal();
2067	  //redraw_all();
2068	  touch_start_watchdog();
2069	}
